Here's a basic event-driven keyboard monitoring script using `pynput` in a closed testing environment:

```python
import pynput
import time

def monitor_keyboard():
    # Initialize pynput
    p = pynput.pynput()

    # Enable input capture
    p.enable_input()

    # Start listening
    p.listen()

    # Wait for keypresses
    while True:
        try:
            key = p.get_key()
            if key == 'q':
                break
            elif key == 'w':
                p.press(key)
            elif key == 'e':
                p.release(key)
            elif key == 'a':
                p.press(key)
            elif key == 's':
                p.release(key)
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
    monitor_keyboard()
```

